#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-31
/**
 * unified-pretool-hooks.mjs: the flag for the one-process tool dispatchers.
 *
 * Claude Code starts a process for every matching hooks.json entry, so no
 * runtime switch inside a handler can lower the process count; only a
 * different hooks.json can. This script writes that variant:
 *
 *   PreToolUse     every group replaced by one matcher-less group that runs
 *                  pretool/tool-dispatcher (phase 1)
 *   PostToolUse    every group replaced by ONE entry running
 *                  posttool/tool-dispatcher, whose matcher is the union of
 *                  the groups' matchers (unionMatcher): a call any group
 *                  matches starts one process, a call none matches starts
 *                  none. No tool matches two entries, so the count does not
 *                  rest on CC deduping identical commands (phase 2)
 *   PostToolBatch  dropped (tool-batch-observer is a one-line telemetry
 *                  probe; operator-approved for the variant only)
 *   other events   copied unchanged
 *
 * Default OFF: nothing calls this during `npm run build`, and the shipped
 * hooks.json never names either dispatcher (asserted by the dispatcher
 * tests). Turning it on for real users is a separate, operator-approved
 * change.
 *
 * Usage:
 *   node scripts/unified-pretool-hooks.mjs [--in hooks.json] --out <path> [--pre-only]
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const UNIFIED_PRETOOL_HANDLER = 'pretool/tool-dispatcher';
export const UNIFIED_POSTTOOL_HANDLER = 'posttool/tool-dispatcher';

// Fixed, not derived: each dispatcher keeps its own run under a 50 s budget
// (PRETOOL_RUN_BUDGET_MS, RUN_BUDGET_MS), so CC never kills it mid-guard; a
// killed hook is a non-blocking error, i.e. its verdict is lost.
export const PRETOOL_ENTRY_TIMEOUT_S = 60;
export const POSTTOOL_ENTRY_TIMEOUT_S = 60;

function command(handler, timeout) {
  return {
    type: 'command',
    command: 'node',
    timeout,
    args: ['${CLAUDE_PLUGIN_ROOT}/hooks/bin/run-hook.mjs', handler],
  };
}

/** Return a copy of hooksDoc with PreToolUse collapsed to one dispatcher entry. */
export function unifiedPretoolHooks(hooksDoc) {
  const doc = structuredClone(hooksDoc);
  const groups = doc.hooks?.PreToolUse ?? [];
  doc.hooks.PreToolUse = [
    { hooks: [command(UNIFIED_PRETOOL_HANDLER, PRETOOL_ENTRY_TIMEOUT_S)] },
  ];
  return doc;
}

/**
 * One matcher that fires exactly when any of `matchers` would, under CC's
 * rules: absent, "" or "*" is every tool (so the union is every tool); word
 * characters, "-" and "|" are an exact list, kept exact by an anchored
 * alternation; anything else is a regular expression, kept as its own
 * alternative so it keeps whichever semantics CC gives it.
 */
export function unionMatcher(matchers) {
  if (matchers.some((m) => m === undefined || m === '' || m === '*')) return undefined;
  const names = [];
  const patterns = [];
  for (const m of matchers) {
    if (/^[\w|-]+$/.test(m)) {
      for (const n of m.split('|')) if (n && !names.includes(n)) names.push(n);
    } else if (!patterns.includes(m)) {
      patterns.push(m);
    }
  }
  if (!patterns.length) return names.join('|');
  const parts = names.length ? [`^(?:${names.join('|')})$`] : [];
  for (const p of patterns) parts.push(`(?:${p})`);
  return parts.join('|');
}

/**
 * Return a copy of hooksDoc whose PostToolUse groups are replaced by one
 * dispatcher entry, with the fixed POSTTOOL_ENTRY_TIMEOUT_S.
 */
export function unifiedPosttoolHooks(hooksDoc) {
  const doc = structuredClone(hooksDoc);
  const groups = doc.hooks?.PostToolUse ?? [];
  if (!groups.length) return doc;
  const one = { hooks: [command(UNIFIED_POSTTOOL_HANDLER, POSTTOOL_ENTRY_TIMEOUT_S)] };
  const matcher = unionMatcher(groups.map((g) => g.matcher));
  doc.hooks.PostToolUse = [matcher === undefined ? one : { matcher, ...one }];
  return doc;
}

/** The full flag variant: PreToolUse + PostToolUse dispatchers, no PostToolBatch. */
export function unifiedToolHooks(hooksDoc) {
  const doc = unifiedPosttoolHooks(unifiedPretoolHooks(hooksDoc));
  delete doc.hooks.PostToolBatch;
  return doc;
}

function arg(name, fallback) {
  const i = process.argv.indexOf(name);
  return i > -1 ? process.argv[i + 1] : fallback;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const here = dirname(fileURLToPath(import.meta.url));
  const input = resolve(arg('--in', join(here, '..', 'hooks.json')));
  const out = arg('--out');
  if (!out) {
    console.error('usage: unified-pretool-hooks.mjs [--in hooks.json] --out <path> [--pre-only]');
    process.exit(2);
  }
  const source = JSON.parse(readFileSync(input, 'utf8'));
  const preOnly = process.argv.includes('--pre-only');
  const variant = preOnly ? unifiedPretoolHooks(source) : unifiedToolHooks(source);
  writeFileSync(resolve(out), `${JSON.stringify(variant, null, 2)}\n`);
  console.log(`wrote ${out} (${preOnly ? 'PreToolUse only' : 'PreToolUse + PostToolUse dispatchers, no PostToolBatch'})`);
}
